from collections.abc import Iterable, Mapping


def aggregate_events(events: Iterable[Mapping[str, object]]) -> dict[str, int]:
    totals: dict[str, int] = {}
    for event in events:
        source, value = event.get("source"), event.get("value")
        if (not isinstance(source, str) or not source.strip()
                or type(value) is not int):
            raise ValueError("invalid parsed event")
        normalized = source.strip()
        totals[normalized] = totals.get(normalized, 0) + value
    return {source: totals[source] for source in sorted(totals)}

