import json


def parse_events(text: str) -> list[dict[str, object]]:
    events: list[dict[str, object]] = []
    for line_number, line in enumerate(text.splitlines(), 1):
        if not line.strip():
            continue
        try:
            event = json.loads(line)
        except json.JSONDecodeError:
            raise ValueError(f"line {line_number} is invalid JSON") from None
        if (not isinstance(event, dict) or set(event) != {"source", "value"}
                or not isinstance(event.get("source"), str)
                or not event["source"].strip()
                or type(event.get("value")) is not int):
            raise ValueError(
                f"line {line_number} must contain source and integer value"
            )
        events.append({"source": event["source"].strip(), "value": event["value"]})
    return events

